    "Tiers {n}, {n} and {n} for {n}–{n}, {n} and {n} heroes (room intensity {n}, progression {n}, points shared by {n} monsters).": "階級 {n}、{n} 和 {n} 分別對應 {n}–{n}、{n} 和 {n} 位英雄（房間強度 {n}，進度 {n}，點數由 {n} 個怪物分攤）。",
