    "Your first interaction": "你的第一個互動",
    "Every map starts with the starting room. Create it with the button on the left.": "每張地圖都從起始房間開始。用左側的按鈕建立它。",
    "Pick a tile in the palette and put it on the board; press R to rotate it. For now, place two different tiles: they will be taken out of the box and set up during the game.": "在調色盤中選擇一個板塊並放到版圖上；按 R 旋轉。現在先放置兩個不同的板塊：遊戲中會將它們從盒子裡拿出來擺設。",
    "The Hero button (H) sets the starting squares of our adventurers. Select 2 to 4 squares in the starting room.": "「英雄」按鈕（H）設定冒險者的起始方格。在起始房間中選擇 2 到 4 個方格。",
    "To reveal the map little by little, we need to create a new room. It appears when an object is used, by programming a trigger that opens a room. Let us try it: click the Object button (O) and pick a door. Then add an “Open a room” trigger.": "為了逐步揭示地圖，我們需要建立一個新房間。它會在物件被使用時出現，方法是設定一個開啟房間的觸發器。來試試看：點擊「物件」按鈕（O）並選擇一扇門。然後加入「開啟房間」觸發器。",
    "You have created your first interaction with the scenery. In the game, the hero will open the door and release the tiles of the next room. Now, let us fill that room: put a chest in a room and program a trigger that gives items to the players (the other buttons and triggers wait for this).": "你已經建立了第一個與場景的互動。在遊戲中，英雄會打開門，放出下一個房間的板塊。現在來填滿那個房間：在房間裡放一個寶箱，並設定一個給玩家物品的觸發器（其他按鈕和觸發器會在這之後開放）。",
    "📂 Import a save of the game (.sav)": "📂 匯入遊戲存檔（.sav）",
    "Clear all": "全部清除",
    "Search an item…": "搜尋物品…",
    "Only what the party has": "只顯示團隊擁有的",
    "skills": "技能",
    "Others": "其他",
    "Clear the whole starting inventory?": "清除整個起始庫存？",
    "Replace the starting inventory with the one of this save?": "用此存檔的起始庫存取代目前的起始庫存？",
    "Imported from the save": "從存檔匯入",
    "This file is not a save of the game.": "此檔案不是遊戲存檔。",
    "For a party of veterans: what it already holds when the campaign starts, won in earlier battles. The party receives it when the campaign begins. Items come from the Workshop (Items and Weapons tabs), the skills from the Skills tab (or the game’s). The item pools of the generated maps leave out the unique items the party already has, and the game never gives an item twice.": "給老練的團隊：戰役開始時他們已經擁有的東西，是在先前戰鬥中贏得的。團隊會在戰役開始時收到這些。物品來自工作坊（「物品」與「武器」分頁），技能來自「技能」分頁（或遊戲的技能）。生成地圖的物品池會排除團隊已擁有的獨特物品，遊戲也絕不會重複給予同一個物品。",
    "Starting gold": "起始金幣",
