    "Recalculate tier {n} from tier {n} with the game’s curve? Their current numbers are replaced.": "要依遊戲的曲線重新計算階級 {n}（以階級 {n} 為基準）嗎？目前的數值將被取代。",
    "Recalculate tiers {n}–{n} from tier {n} with the game’s curve? Their current numbers are replaced.": "要依遊戲的曲線重新計算階級 {n}–{n}（以階級 {n} 為基準）嗎？目前的數值將被取代。",
    "OK: first move all its triggers to another object (you click it), then delete.": "確定：先將它的所有觸發器移到另一個物件（由你點擊選擇），再刪除。",
    "Cancel: delete anyway; the room stays without an opener until another object gets an “{q}” trigger.": "取消：仍然刪除；在其他物件獲得「{Q}」觸發器之前，該房間將沒有開啟方式。",
    "This is the only trigger that opens room {n}.": "這是唯一能開啟房間 {n} 的觸發器。",
    "Cancel: delete the trigger; the room stays without an opener until another object gets an “{q}” trigger.": "取消：刪除觸發器；在其他物件獲得「{Q}」觸發器之前，該房間將沒有開啟方式。",
    "Removal trigger(s) added to “{q}”. Place the pillar again.": "已將移除觸發器加入「{Q}」。請重新放置柱子。",
