    "the intensity of the rooms with monsters and of the triggers that call monsters from the pool, all by the same step (from −6 to +6, always within 1 to 10);": "有怪物的房間的強度，以及從生成池召喚怪物的觸發器強度，全部以相同的級距調整（從 −6 到 +6，始終在 1 到 10 之間）；",
    "the tiers for 1–2, 3 and 4 heroes of the monsters placed by hand, by the game's rule (as ⚖ Balance on a monster).": "手動放置的怪物在 1–2、3 和 4 位英雄時的階級，依遊戲規則調整（如同怪物上的 ⚖ 平衡）。",
    "the campaign progression, the monster and item pools, the monsters themselves, the objects, the triggers and the texts.": "戰役進度、怪物池和物品池、怪物本身、物件、觸發器和文字。",
    "Work out the proposal": "計算提案",
