    "Click a second object, not the one that moves.": "點擊第二個物件，而不是要移動的那個。",
    "Click the marker: the same tile laid again, where it goes.": "點擊標記：在要去的地方再放一次的同一個板塊。",
    "Click the marker tile.": "點擊標記板塊。",
    "marker": "標記",
    "Move the tile": "移動板塊",
    "Lays this one as the marker; then click the object whose use moves the tile.": "將這個放作標記；然後點擊使用後會移動板塊的物件。",
    "Remove only that tile, keeping objects and monsters": "只移除那個板塊，保留物件和怪物",
