    "drag to pan": "拖曳以平移",
    "floor": "地面",
    "level {n} medium or tall": "層級 {n} 可用中柱或高柱",
    "level {n} tall. (P)": "層級 {n} 只能用高柱。（P）",
    "marks the squares where the heroes start, in the starting room ({n} to {n} squares). The players put their figures there before the first room appears.": "標記英雄在起始房間中起始的方格（{n} 到 {n} 個方格）。玩家會在第一個房間出現之前，把模型放在那裡。",
    "same-level tiles cannot overlap. Underlays go under the tiles. (T)": "同層級的板塊不能重疊。底板放在板塊下方。（T）",
    "to see the map in relief: elevated tiles, pillars, stairs and ladders.": "以立體方式查看地圖：高架板塊、柱子、樓梯和梯子。",
    "wheel zooms": "滾輪縮放",
    "↻ Rotate": "↻ 旋轉",
