    "🗑 Clear Map": "🗑 清除地圖",
    "+ Another like this": "+ 再加一個同樣的",
    "Balance: sets the tiers for {n}–{n}, {n} and {n} heroes by the game's points (room intensity ÷ {n} × heroes × {n} × progression, shared by the monsters placed in this room), each one above the other": "平衡：設定 {n}–{n}、{n} 和 {n} 位英雄時的階級，依遊戲的點數（房間強度 ÷ {n} × 英雄數 × {n} × 進度，由此房間中放置的怪物分攤），每一個都高於前一個",
    "Edit in the workshop": "在工作坊中編輯",
    "Like the game's bosses (Levirax: tier {n}, {n} or {n} for {n}, {n} or {n} heroes). The difficulty (Journey, Heroic, Warfare) still applies on top.": "就像遊戲中的首領（雷維拉克斯：階級 {n}、{n} 或 {n}，分別對應 {n}、{n} 或 {n} 位英雄）。難度（旅行、英勇、戰爭）仍會另外套用。",
    "Room intensity": "房間強度",
    "Tier": "階級",
    "Tier by the number of heroes": "依英雄數量的階級",
    "Triggers of this monster: they run every time it is defeated, after the game’s own effects (loot, objectives). Taking it off with “{q}” does not count.": "此怪物的觸發器：每次它被擊敗時，在遊戲本身的效果（戰利品、目標）之後執行。用「{Q}」移除它不算數。",
    "When defeated": "被擊敗時",
    "atk {n}": "攻 {n}",
    "def {n}": "防 {n}",
    "present from the start": "從一開始就在場",
    "{n} (= monsters here, default)": "{n}（＝此處的怪物，預設）",
    "{n} heroes": "{n} 位英雄",
    "{n}–{n} heroes": "{n}–{n} 位英雄",
    "⚖ Balance": "⚖ 平衡",
    "Clear the map?": "清除地圖？",
    "Clear without exporting": "不匯出直接清除",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop, the other maps, the campaign and the author stay. Files already exported stay in the folder.": "這會清除地圖「{Q}」的 {n} 個房間：板塊、柱子、物件、怪物、英雄格及其觸發器，以及它的名稱和地圖設定（文字、音樂、任務、生成池、計數器）。工作坊、其他地圖、戰役和作者會保留。已匯出的檔案仍留在資料夾中。",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers, and its name and map setup (texts, music, mission, pools, counters). The workshop and the author stay. Files already exported stay in the folder.": "這會清除地圖「{Q}」的 {n} 個房間：板塊、柱子、物件、怪物、英雄格及其觸發器，以及它的名稱和地圖設定（文字、音樂、任務、生成池、計數器）。工作坊和作者會保留。已匯出的檔案仍留在資料夾中。",
    "The map has nothing to clear.": "地圖上沒有可清除的東西。",
    "Do you want to export it before clearing?": "清除之前要先匯出嗎？",
    "Everything not exported is lost.": "所有未匯出的內容都會遺失。",
    "Export, then clear": "先匯出，再清除",
    "This erases the {n} room(s) of the map “{q}”: tiles, pillars, objects, monsters, hero spaces and their triggers. The workshop, the map setup (name, texts, music, pools), the other maps and the campaign stay. Files already exported stay in the folder.": "這會清除地圖「{Q}」的 {n} 個房間：板塊、柱子、物件、怪物、英雄格及其觸發器。工作坊、地圖設定（名稱、文字、音樂、生成池）、其他地圖和戰役會保留。已匯出的檔案仍留在資料夾中。",
    "Writes the .bcamp and its maps (download), then clears.": "寫出 .bcamp 及其地圖（下載），然後清除。",
    "(a hero uses it: tap it with the hero chosen)": "（英雄使用它：選擇英雄後點擊它）",
