    "Tapped with no hero, it only shows the text when looked at.": "沒有英雄時點擊，只會顯示查看時的文字。",
    "Text when used": "使用時的文字",
    "They run in order when a hero uses the object. A requirement goes inside the box of a trigger (open it) and holds back only that trigger.": "英雄使用物件時，它們會依序執行。需求放在觸發器的方塊內（展開它），只會阻擋該觸發器。",
