    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: medium pillar, tall pillar.": "還沒有：在它的插槽上使用柱子工具（功能區的層級 ${p.level}）。此處允許：中柱、高柱。",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: short pillar, medium pillar, tall pillar.": "還沒有：在它的插槽上使用柱子工具（功能區的層級 ${p.level}）。此處允許：短柱、中柱、高柱。",
    "None yet: use the Pillar tool on its sockets (level ${p.level} on the ribbon). Allowed here: tall pillar.": "還沒有：在它的插槽上使用柱子工具（功能區的層級 ${p.level}）。此處允許：高柱。",
    "Pillars of this tile": "此板塊的柱子",
    "Room {n}: tile {n}A is elevated (level {n}) with no pillars.": "房間 {n}：板塊 {n}A 是高架板塊（層級 {n}），但沒有柱子。",
