    "Name": "名稱",
    "New rooms are born from an object: select it, add the trigger “{q}”. Pick a room here before touching what is in it.": "新房間由物件產生：選取物件，加入「{Q}」觸發器。編輯房間內的東西之前，請先在這裡選擇一個房間。",
    "Room {n}: tile {n}B is elevated (level {n}) with no pillars.": "房間 {n}：板塊 {n}B 是高架板塊（層級 {n}），但沒有柱子。",
