    "). Which monster of the pool enters is drawn in the game.": "）。生成池中的哪個怪物進場，會在遊戲中抽選。",
    "+ Another space": "+ 再一個格子",
    "Intensity of this room": "此房間的強度",
    "Tier range {n}–{n}, campaign progression {n} (": "階級範圍 {n}–{n}，戰役進度 {n}（",
    "What the game would do": "遊戲會怎麼做",
    "When the group is defeated": "當群組被擊敗時",
    "When the room starts, the game fills these spaces with its own rule for random spawns: points = intensity ÷ {n} × heroes × {n} × progression; it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "房間開始時，遊戲會以它自己的隨機生成規則填滿這些格子：點數 = 強度 ÷ {n} × 英雄數 × {n} × 進度；它會取用點數負擔得起的地圖範圍內最高階級（費用 {n}、{n}、{n}、{n}、{n}、{n}…），生成池中擁有該階級的怪物會進場，每格一個（最多 {n} 個），直到點數用完。剩餘的點數會轉到下一個平衡房間。可能全部進場，也可能只有一個強大的怪物。",
    "change": "變更",
    "it takes the highest tier of the map’s range the points pay for (costs {n}, {n}, {n}, {n}, {n}, {n}…), and monsters of the pool that have that tier enter, one per space (up to {n}), while the points last. Leftover points go to the next balanced room. All may enter, or just one strong monster.": "它會取用點數負擔得起的地圖範圍內最高階級（費用 {n}、{n}、{n}、{n}、{n}、{n}…），生成池中擁有該階級的怪物會進場，每格一個（最多 {n} 個），直到點數用完。剩餘的點數會轉到下一個平衡房間。可能全部進場，也可能只有一個強大的怪物。",
    "{n} (= spaces, default)": "{n}（＝格子數，預設）",
