    "Play a scene, video or sound": "播放場景、影片或聲音",
    "Play what?": "要播放什麼？",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, spawn monsters, a tile, a room, an object, a monster)": "在遊戲進行中將東西放上版圖或移除：板塊、物件、怪物、房間。（板塊、物件、生成怪物、板塊、房間、物件、怪物）",
    "Remove…": "移除…",
    "Something appears on the board: a tile, an object or monsters. (a tile, an object, spawn monsters)": "版圖上出現某樣東西：板塊、物件或怪物。（板塊、物件、生成怪物）",
    "Takes something off the board: a tile, a room, an object or monsters. (a tile, a room, an object, a monster)": "從版圖上移除某樣東西：板塊、房間、物件或怪物。（板塊、房間、物件、怪物）",
    "What happens when a hero uses this object. Several triggers run in order.": "英雄使用此物件時會發生什麼。多個觸發器會依序執行。",
    "Puts something on the board, or takes it off, during play: tiles, objects, monsters, rooms. (a tile, an object, a tile, a room, an object, a monster)": "在遊戲進行中將東西放上版圖或移除：板塊、物件、怪物、房間。（板塊、物件、板塊、房間、物件、怪物）",
    "What happens once, when the count reaches {n} (the total of the counter). Several triggers run in order.": "當計數達到 {n}（計數器的總數）時發生一次的事。多個觸發器會依序執行。",
    "When the balanced group is defeated: “{q}”": "當平衡群組被擊敗時：「{Q}」",
    "A goal on this map, announced when the monster is defeated and listed with the objectives. An objective does not end the map: the mission does (Map setup). An objective can be chosen there as the mission.": "這張地圖上的一個目標，在怪物被擊敗時宣告，並列在目標之中。目標不會結束地圖：任務才會（地圖設定）。可以在那裡將某個目標選為任務。",
    "From when the monster is defeated, the round counter runs the triggers inside: every N rounds (as many times as you say, or to the end of the map), or once, N rounds later. For a wave, put “{q}” inside: the spawn has its own “{q}”.": "從怪物被擊敗起，輪數計數器會執行其中的觸發器：每 N 輪一次（依你指定的次數，或直到地圖結束），或在 N 輪後執行一次。若要產生一波敵人，請在其中放入「{Q}」：生成有它自己的「{Q}」。",
    "When this monster is defeated: “{q}”": "當此怪物被擊敗時：「{Q}」",
    "If the test fails: “{q}”": "如果檢定失敗：「{Q}」",
    "After answer {n}: “{q}”": "回答 {n} 之後：「{Q}」",
    "When the rounds come: “{q}”": "當輪數到達時：「{Q}」",
    "\"{q}\": scene without text": "「{Q}」：沒有文字的場景",
