    "Loot points": "戰利品點數",
    "Materials of the item pool (Map setup) are drawn until they add up to these points (each unit is worth its value: base materials {n}, essences {n} to {n}).": "從物品池（地圖設定）中抽選材料，直到總和達到這些點數（每單位依其價值計算：基礎材料 {n}，魔素 {n} 到 {n}）。",
    "No item yet": "還沒有物品",
    "Open the item pool": "開啟物品池",
    "Pick the item…": "選擇物品…",
    "Random materials from the item pool (worth N loot points)": "物品池中的隨機材料（價值 N 戰利品點數）",
    "The item pool has no items.": "物品池沒有物品。",
