    "Takes one tile off the board with everything on it (objects, pillars, monsters). Frees it for reuse in a later room.": "從版圖上移除一個板塊及其上的所有東西（物件、柱子、怪物）。釋出該板塊，以便在之後的房間中重複使用。",
    "Tile:": "板塊：",
