    "{n} in the roster": "名單中有 {n} 位",
    "The six profiles of the game (class, weapons, skills and feats) go into the campaign. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "遊戲的六個身分（職業、武器、技能和成就）會進入戰役。每個身分由遊戲的英雄扮演（和遊戲中一樣），或由你名單中的英雄扮演，在該英雄自己的表單中指定。",
    "The six profiles of the game (class, weapons, skills and feats) go into the map. Each is played by the game’s hero (as in the game) or by a hero of your roster, put in it on the hero’s own sheet.": "遊戲的六個身分（職業、武器、技能和成就）會進入地圖。每個身分由遊戲的英雄扮演（和遊戲中一樣），或由你名單中的英雄扮演，在該英雄自己的表單中指定。",
