    "+ New hero": "+ 新英雄",
    "From an NPC…": "從 NPC 建立…",
    "profile": "身分",
    "the game’s hero, out: another plays this profile": "遊戲的英雄，已離開：由其他英雄扮演此身分",
    "not in the profiles": "不在身分中",
    "New hero": "新英雄",
    "The Workshop has no NPC yet.": "工作坊還沒有 NPC。",
