    "out: played by": "已離開：扮演者為",
    "Profile in the campaign": "戰役中的身分",
    "Profile in the map": "地圖中的身分",
    "None: stays in the roster": "無：留在名單中",
    "Delete hero": "刪除英雄",
    "The animated drawing of the game hero of its profile.": "它身分所屬遊戲英雄的動畫圖像。",
    "(the profile’s)": "（身分的）",
    "Each weapon has one hero in the game (its parts, the shop, the inventory and the feats follow it). Picking the weapon of another hero hands him this one in exchange. The numbers come from the weapons: they are changed in the Weapons tab. The weapons belong to the profile: they stay with it if the hero leaves.": "每把武器在遊戲中都屬於一位英雄（它的部件、商店、庫存和成就都跟隨它）。選擇另一位英雄的武器，會把這把武器交換給他。數值來自武器：在「武器」分頁中修改。武器屬於身分：如果英雄離開，武器會留在身分上。",
    "The weapons belong to the profile: they stay with it if the hero leaves.": "武器屬於身分：如果英雄離開，武器會留在身分上。",
    "went back to the roster.": "已回到名單。",
    "Who plays this profile": "誰扮演此身分",
    "the game’s hero": "遊戲的英雄",
    "now in the profile of": "現在位於以下身分：",
    "Pick a hero of the roster to play this profile in the place of the game’s hero.": "從名單中選擇一位英雄，取代遊戲的英雄扮演此身分。",
    "now plays the profile of": "現在扮演以下英雄的身分：",
    "is back in the profile.": "已回到身分中。",
    "Heads, hafts and grips of the weapons, imported in a package or made here: they are in the Weapons tab, under the weapon they belong to.": "武器的頭部、柄身和握把，從套件匯入或在這裡製作：它們位於「武器」分頁中所屬的武器底下。",
    "{n} new part(s)": "{n} 個新部件",
    "Charms a hero carries; some have an effect the app applies.": "英雄攜帶的護符；有些具有 App 會套用的效果。",
    "Crafting materials: loot is paid in them and recipes cost them.": "製作材料：戰利品以它們支付，製作指南需要花費它們。",
    "Tick several entries of this tab and delete them at once": "勾選此分頁中的多個條目並一次刪除",
