    "Charms a hero carries; some have an effect the app applies. Only items listed in the workshop can be given by triggers, rewards and dialogues, dropped by monsters or crafted.": "英雄攜帶的護符；有些具有 App 會套用的效果。只有列在工作坊中的物品，才能由觸發器、獎勵和對話給予、由怪物掉落或被製作。",
    "Choose the type first: it decides the figure and the animated art in the app (the game has no others) and the behaviour rules of that family. Then the rest of the sheet opens.": "請先選擇類型：它決定 App 中的模型和動畫美術（遊戲沒有其他的），以及該家族的行為模式規則。然後表單的其餘部分才會開放。",
