    "the text is what the players read.": "文字是玩家閱讀的內容。",
    "the wheel (or the slider) changes the size of the chosen piece, Shift+wheel, Q/E or the turn slider rotate it, the arrows nudge it. A piece only shows inside its own box: what goes out of it is cut (shown faint).": "滾輪（或滑桿）可變更所選部件的大小，Shift+滾輪、Q/E 或旋轉滑桿可旋轉它，方向鍵可微調。部件只會在它自己的框內顯示：超出的部分會被裁切（以淡色顯示）。",
    "three parts": "三個部件",
    "tier": "階級",
    "too few, or weak ones, leave the heroes behind the monsters. Pick them on purpose, thinking of the heroes' progress along the map.": "太少或太弱，則會讓英雄落後於怪物。請有意識地挑選，考量英雄在整張地圖中的成長。",
    "turns each piece into a picture of the exact size of its box and puts it in the weapon.": "將每個部件轉成與它的框大小完全相同的圖片，並放進武器中。",
