    "Monsters the “{q}” trigger draws from. Each room starts with this list and may adjust it.": "「{Q}」觸發器抽選怪物的來源。每個房間一開始都使用這份清單，並可以調整它。",
    "NPCs": "NPC",
    "Pick an entry on the left, import one from the game, or create a new one.": "在左側選擇一個條目、從遊戲匯入一個，或建立一個新的。",
