    "A new map (it goes after the selected card)": "新地圖（它會接在選取的卡片之後）",
    "A new side quest (it goes after the selected card)": "新支線任務（它會接在選取的卡片之後）",
    "Appears on the world map on its own when unlocked": "解鎖時自行出現在世界地圖上",
    "Auto-arrange": "自動排列",
    "Box": "對話框",
    "Box (first)": "對話框（第一個）",
    "Box {n}": "對話框 {n}",
    "Boxes of text, questions and videos (your own films), played in a row (it goes after the selected card)": "文字對話框、問題和影片（你自己的影片），依序播放（它會接在選取的卡片之後）",
    "Boxes of “{q}”: drag from a box’s ● (or an answer’s ●) onto another box to say what comes next": "「{Q}」的對話框：從對話框的 ●（或回答的 ●）拖曳到另一個對話框，指定接下來是什麼",
    "Boxes play in the order of the arrows, starting at the first. A question box branches: each answer leads to its own next box. A video box plays your own film (MP{n} or WebM) between the other boxes.": "對話框依箭頭的順序播放，從第一個開始。問題對話框會產生分支：每個回答通往它自己的下一個對話框。影片對話框會在其他對話框之間播放你自己的影片（MP{n} 或 WebM）。",
    "Build the rooms of this map": "建造這張地圖的房間",
    "Build the rooms of this side quest": "建造這個支線任務的房間",
    "Build the rooms ▸": "建造房間 ▸",
    "Campaign ▸": "戰役 ▸",
    "City": "城市",
    "City visit": "城市造訪",
