    "City visit (plays the next time the party enters the city)": "城市造訪（團隊下次進入城市時播放）",
    "Comes after (arrows into it)": "接在之後（指向它的箭頭）",
    "Crafting materials": "製作材料",
    "the bell hangs in its frame: a bell on the table takes the bell frame, and with one frame only one bell hangs at a time": "鐘掛在鐘架上：桌上的一個鐘需要一個鐘架，而只有一個鐘架時，同一時間只能掛一個鐘",
    "Del deletes": "Del 刪除",
    "Delete campaign": "刪除戰役",
    "Delete for good": "永久刪除",
