    "Original maps": "原始地圖",
    "The original maps of the game are read by the Bigorna mod from your own copy of the game: start the game once with the mod installed (the title screen prepares them), then open the editor from the Editor folder of the game again.": "遊戲的原始地圖由 Bigorna mod 從你自己的遊戲副本中讀取：在安裝 mod 的情況下啟動一次遊戲（標題畫面會準備它們），然後再從遊戲的 Editor 資料夾重新開啟編輯器。",
    "The quests of the game, converted into maps of the editor: tiles, objects, rooms, monsters and the logic the triggers can say.": "遊戲的任務，轉換成編輯器的地圖：板塊、物件、房間、怪物，以及觸發器能表達的邏輯。",
    "Each map comes with notes on what was simplified (Map setup).": "每張地圖都附有說明，列出哪些地方被簡化了（地圖設定）。",
