    "Click the object or monster that will open the new room: it gets the trigger “Open a room”. Esc cancels.": "點擊會開啟新房間的物件或怪物：它會獲得「開啟房間」觸發器。按 Esc 取消。",
    "Click an object or a monster of the map (staircases and bridges are floor).": "點擊地圖上的一個物件或怪物（樓梯和橋屬於地面）。",
    "the balanced group of this room": "此房間的平衡群組",
