    "The edges nearest to it": "離它最近的邊緣",
    "That room has no free edge for a new room: pick an object of another room.": "該房間沒有可供新房間使用的空閒邊緣：請選擇另一個房間的物件。",
    "The one you pick appears on the board, framed and marked “preview” in the list of rooms, so you see it in place.": "你選擇的候選會出現在版圖上，加上外框，並在房間清單中標記為「預覽」，讓你看到它就定位的樣子。",
