    "The spawn pool of the map is empty: add monsters to it (Map setup) so the balanced spaces have something to draw.": "地圖的生成池是空的：請為它加入怪物（地圖設定），讓平衡格有東西可以抽選。",
    "Archetypes of the generator": "產生器的原型",
