    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen (or comes as a new map of the campaign), fully editable.": "一整張地圖：英雄為何進入（前提）、他們必須做什麼才能獲勝（目標）、過程中會改變什麼（額外規則）、緊張感如何升高以及結局。它會取代畫面上的地圖（或成為戰役的新地圖），完全可編輯。",
