    "Update": "更新",
    "Workshop packages shared by other authors. A package downloaded here goes into your library (⚙ → My packages), ready to add to any map or campaign.": "其他作者分享的工作坊套件。在這裡下載的套件會進入你的套件庫（⚙ → 我的套件），可以加入任何地圖或戰役。",
