    "Change it here: changed, it becomes yours, with the same id (what uses it gets your version; the package’s file stays as it is). To take it out, remove the package (📚 My packages).": "在這裡修改它：修改後它就屬於你，使用相同的 id（使用它的內容會取得你的版本；套件的檔案保持原樣）。要移除它，請移除該套件（📚 我的套件）。",
    "It replaces the map on screen, fully editable.": "它會取代畫面上的地圖，完全可編輯。",
    "A whole map: why the heroes go in (premise), what they must do to win (objective), what changes along the way (extra rule), how the tension grows and the end. It replaces the map on screen, fully editable.": "一整張地圖：英雄為何進入（前提）、他們必須做什麼才能獲勝（目標）、過程中會改變什麼（額外規則）、緊張感如何升高以及結局。它會取代畫面上的地圖，完全可編輯。",
    "Add to the campaign": "加入戰役",
    "Monsters in a room": "房間中的怪物",
    "A long, narrow way: whoever holds the narrow part holds the room.": "一條狹長的道路：誰守住狹窄處，誰就掌控這個房間。",
    "Wide and open: a straight fight with room to move.": "寬敞開闊：有移動空間的正面對決。",
    "Few or no monsters, several points of interest to search and a clue.": "怪物很少或沒有，有幾個可搜尋的興趣點和一條線索。",
    "The reward, guarded or not: chests at the back, a price to reach them.": "獎勵，有人守護或沒有：寶箱在後方，要付出代價才能拿到。",
    "A calm place to breathe, heal and talk: no monsters, a little to find.": "一個可以喘息、治療和交談的平靜之處：沒有怪物，有一點東西可以找。",
    "The last room: large, with cover and a strong foe at the back.": "最後的房間：寬大，有掩護，後方有強大的敵人。",
    "The way is blocked by water, fire or rubble: go around, or through it.": "道路被水、火或瓦礫阻擋：繞過去，或穿過去。",
    "A raised platform over the floor: whoever holds the height sees everything.": "高於地面的平台：誰佔據高處，誰就能看清一切。",
    "Moving: drag the room · R turns it · Esc or a click outside ends it": "移動中：拖曳房間 · R 旋轉 · Esc 或點擊外部結束",
    "Click the outline to move the room · R turns it": "點擊外框以移動房間 · R 旋轉",
    "The room has no tiles to turn.": "房間沒有可以旋轉的板塊。",
