    "This erases everything the editor keeps: the map or campaign on screen, the Workshop (monsters, items, materials, objects, imported or made), the packages (in the app: the Pacotes folder, every package in it), the pictures kept by the editor, the quick save, your archetypes, the hints and warnings, window positions and sizes, the author, the export folder and the autosave.": "這會清除編輯器保存的所有內容：畫面上的地圖或戰役、工作坊（怪物、物品、材料、物件，無論是匯入或製作的）、套件（在 App 中：Pacotes 資料夾及其中的每個套件）、編輯器保存的圖片、快速存檔、你的原型、提示與警告、視窗位置與大小、作者、匯出資料夾和自動存檔。",
    "Reset everything: the work on screen, the Workshop and the packages, the pictures kept, the quick save, archetypes, tips and warnings, window positions and sizes, author, export folder and autosave. The language stays.": "重設所有內容：畫面上的作品、工作坊和套件、保存的圖片、快速存檔、原型、提示與警告、視窗位置與大小、作者、匯出資料夾和自動存檔。語言會保留。",
