    "Skill": "技能",
    "it stands on the game box of Act I, with its floor at level 3 and its walls 2 above. It takes no pillars.": "它立在第一幕的遊戲盒上，地面位於層級 3，牆在其上方 2 層。它不需要柱子。",
    "it stands on the floor, with its walls 2 above it. It takes no pillars; it may stand on the game box (all its squares over the box).": "它立在地面上，牆在其上方 2 層。它不需要柱子；它可以立在遊戲盒上（它的所有方格都在盒子上方）。",
    "Moving: drag the room · Esc or a click outside ends it": "移動中：拖曳房間 · Esc 或點擊外部結束",
    "Click the outline to move the room": "點擊外框以移動房間",
    "The room overlapped another one: it went back to where it was.": "房間與另一個房間重疊：已回到原位。",
    "Room moved.": "房間已移動。",
    "Room moved: it is apart from the others now (no door joins it).": "房間已移動：它現在與其他房間分開（沒有門與它相連）。",
    "Moving ended.": "移動結束。",
